// WpColorManagementOutputV1Listener receives the events of a wp_color_management_output_v1 object.
pub interface WpColorManagementOutputV1Listener {
	// This event is sent whenever the image description of the output changed,
	// followed by one wl_output.done event common to output events across all
	// extensions. If the client wants to use the updated image description, it
	// needs to do get_image_description again, because image description objects
	// are immutable.
