// WpImageDescriptionV1 is a client side proxy for wp_image_description_v1.
// An image description carries information about the pixel color encoding
// and its intended display and viewing environment. The image description is
// attached to a wl_surface via
// wp_color_management_surface_v1.set_image_description. A compositor can use
// this information to decode pixel values into colorimetrically meaningful
// quantities, which allows the compositor to transform the surface contents
// to become suitable for various displays and viewing environments. Note,
// that the wp_image_description_v1 object is not ready to be used
// immediately after creation. The object eventually delivers either the
// 'ready' or the 'failed' event, specified in all requests creating it. The
// object is deemed "ready" after receiving the 'ready' event. An object
// which is not ready is illegal to use, it can only be destroyed. Any other
// request in this interface shall result in the 'not_ready' protocol error.
// Attempts to use an object which is not ready through other interfaces
// shall raise protocol errors defined there. Once created and regardless of
// how it was created, a wp_image_description_v1 object always refers to one
// fixed image description. It cannot change after creation.
pub struct WpImageDescriptionV1 {
	wayland.Object
}

// wp_image_description_v1_proxy wraps an object id in a WpImageDescriptionV1 proxy.
pub fn wp_image_description_v1_proxy(conn &wayland.Connection, id u32) WpImageDescriptionV1 {
	return WpImageDescriptionV1{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wp_image_description_v1'
		}
	}
}

// WpImageDescriptionV1Listener receives the events of a wp_image_description_v1 object.
pub interface WpImageDescriptionV1Listener {
	// If creating a wp_image_description_v1 object fails for a reason that is
	// not defined as a protocol error, this event is sent. The requests that
	// create image description objects define whether and when this can occur.
	// Only such creation requests can trigger this event. This event cannot be
	// triggered after the image description was successfully formed. Once this
	// event has been sent, the wp_image_description_v1 object will never become
	// ready and it can only be destroyed.
mut:
	failed(proxy WpImageDescriptionV1, cause u32, msg_ string)
	// Starting from interface version 2, the 'ready2' event is sent instead of
	// this event. For the definition of this event, see the 'ready2' event. The
	// difference to this event is as follows. The id number is valid only as
	// long as the protocol object is alive. If all protocol objects referring to
	// the same image description record are destroyed, the id number may be
	// recycled for a different image description record.
	ready(proxy WpImageDescriptionV1, identity u32)
	// Once this event has been sent, the wp_image_description_v1 object is
	// deemed "ready". Ready objects can be used to send requests and can be used
	// through other interfaces. Every ready wp_image_description_v1 protocol
	// object refers to an underlying image description record in the compositor.
	// Multiple protocol objects may end up referring to the same record. Clients
	// may identify these "copies" by comparing their id numbers: if the numbers
	// from two protocol objects are identical, the protocol objects refer to the
	// same image description record. Two different image description records
	// cannot have the same id number simultaneously. The id number does not
	// change during the lifetime of the image description record. Image
	// description id number is not a protocol object id. Zero is reserved as an
	// invalid id number. It shall not be possible for a client to refer to an
	// image description by its id number in protocol. The id numbers might not
	// be portable between Wayland connections. A compositor shall not send an
	// invalid id number. Compositors must not recycle image description id
	// numbers. This identity allows clients to de-duplicate image description
	// records and avoid get_information request if they already have the image
	// description information.
	ready2(proxy WpImageDescriptionV1, identity_hi u32, identity_lo u32)
