			icc_size := msg.arg_u32(1)!
			s.listener.icc_file(s.proxy, icc, icc_size)
		}
		2 {
			r_x := msg.arg_int(0)!
			r_y := msg.arg_int(1)!
			g_x := msg.arg_int(2)!
			g_y := msg.arg_int(3)!
			b_x := msg.arg_int(4)!
			b_y := msg.arg_int(5)!
			w_x := msg.arg_int(6)!
			w_y := msg.arg_int(7)!
			s.listener.primaries(s.proxy, r_x, r_y, g_x, g_y, b_x, b_y, w_x, w_y)
		}
		3 {
			primaries := msg.arg_u32(0)!
			s.listener.primaries_named(s.proxy, primaries)
		}
		4 {
			eexp := msg.arg_u32(0)!
			s.listener.tf_power(s.proxy, eexp)
		}
		5 {
			tf := msg.arg_u32(0)!
			s.listener.tf_named(s.proxy, tf)
		}
		6 {
			min_lum := msg.arg_u32(0)!
			max_lum := msg.arg_u32(1)!
			reference_lum := msg.arg_u32(2)!
			s.listener.luminances(s.proxy, min_lum, max_lum, reference_lum)
		}
		7 {
			r_x := msg.arg_int(0)!
			r_y := msg.arg_int(1)!
			g_x := msg.arg_int(2)!
			g_y := msg.arg_int(3)!
			b_x := msg.arg_int(4)!
			b_y := msg.arg_int(5)!
			w_x := msg.arg_int(6)!
			w_y := msg.arg_int(7)!
			s.listener.target_primaries(s.proxy, r_x, r_y, g_x, g_y, b_x, b_y, w_x, w_y)
		}
		8 {
			min_lum := msg.arg_u32(0)!
			max_lum := msg.arg_u32(1)!
			s.listener.target_luminance(s.proxy, min_lum, max_lum)
		}
		9 {
			max_cll := msg.arg_u32(0)!
			s.listener.target_max_cll(s.proxy, max_cll)
		}
		10 {
			max_fall := msg.arg_u32(0)!
			s.listener.target_max_fall(s.proxy, max_fall)
